let mingMapEchartsReady = false;

// Ghi nhớ lớp và trạng thái viewport
let mingMapCurrentLevel = 'nation'; 
let mingMapCurrentProvince = null;
let mingMapCurrentPrefecture = null;
let mingMapNationGeoJSON = null; 
